const SYSTEM_INFO = uni.getSystemInfoSync()
const menuButtonInfo = typeof uni.getMenuButtonBoundingClientRect === 'function'
  ? uni.getMenuButtonBoundingClientRect()
  : null

export const getStatusBarHeight = () => SYSTEM_INFO.statusBarHeight || 0

// 导航栏高度
export const getNavBarHeight = () => {
  if (menuButtonInfo) {
    return (menuButtonInfo.top - SYSTEM_INFO.statusBarHeight) * 2 + menuButtonInfo.height
  } else {
    return 60 // 默认导航栏高度
  }
}

export const getLeftIcon = () => {
	// #ifdef MP-TOUTIAO
		if(tt.getCustomButtonBoundingClientRect) {
			const { leftIcon:{ right}} = tt.getCustomButtonBoundingClientRect()
			return right + 5
		}
		else {
			return 0
		}
	// #endif
}
